#&gt; 2 [0,0.75]     0.5  2.12   0.5  1.87  2.18  2.56
#&gt; 3 [0,0.75]     0.5  3.53   0.9  2.98  3.59  4.33
#&gt; 4 (0.75,1.5]   1    2.06   0.1  1.60  1.95  2.34
#&gt; 5 (0.75,1.5]   1    3.01   0.5  2.68  3.02  3.42
#&gt; 6 (0.75,1.5]   1    4.25   0.9  3.86  4.45  5.16


vpc_plot &lt;- function(vpc, obs) {
  ggplot(vpc, aes(time)) +
    geom_ribbon(aes(ymin = lo, ymax = hi, group = prob,
                    fill = ifelse(prob == 0.5, "median", "10th / 90th")), alpha = 0.3) +
    geom_point(data = obs, aes(TIME, DV), size = 0.6, alpha = 0.3) +
    geom_line(aes(y = value, group = prob, linetype = ifelse(prob == 0.5, "median", "10th / 90th"))) +
    scale_y_log10() +
    labs(x = "Time (h)", y = "Concentration", fill = "Simulated", linetype = "Observed")
}
vpc_plot(vpc, obs)






Figure 8.1: VPC of the base model: observed 10th, 50th and 90th percentiles (lines) with 90% intervals of the simulated percentiles (bands). Observations as points.




Read a VPC by checking whether each observed percentile line stays inside its simulated band. A line that leaves its band over a range of times points to a misspecification there: in structure, in variability (the outer percentiles) or in residual error.

